bool MagmaAuditLog::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("business_id"))
    {
        if(!validJsonOfField(1, "business_id", pJson["business_id"], err, true))
            return false;
    }

    if(pJson.isMember("actor_type"))
    {
        if(!validJsonOfField(2, "actor_type", pJson["actor_type"], err, true))
            return false;
    }

    if(pJson.isMember("actor_id"))
    {
        if(!validJsonOfField(3, "actor_id", pJson["actor_id"], err, true))
            return false;
    }

    if(pJson.isMember("action"))
    {
        if(!validJsonOfField(4, "action", pJson["action"], err, true))
            return false;
    }

    else
    {
        err="The action column cannot be null";
        return false;
    }

    if(pJson.isMember("entity"))
    {
        if(!validJsonOfField(5, "entity", pJson["entity"], err, true))
            return false;
    }

    else
    {
        err="The entity column cannot be null";
        return false;
    }

    if(pJson.isMember("entity_id"))
    {
        if(!validJsonOfField(6, "entity_id", pJson["entity_id"], err, true))
            return false;
    }

    if(pJson.isMember("before"))
    {
        if(!validJsonOfField(7, "before", pJson["before"], err, true))
            return false;
    }

    if(pJson.isMember("after"))
    {
        if(!validJsonOfField(8, "after", pJson["after"], err, true))
            return false;
    }

    if(pJson.isMember("ip_address"))
    {
        if(!validJsonOfField(9, "ip_address", pJson["ip_address"], err, true))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(10, "created_at", pJson["created_at"], err, true))
            return false;
    }

    return true;
}
